prompt:
Validate the proposed CTL2 implementation against the original request. Focus on CTL2 syntax and whether the implementation satisfies the requested business logic.

ORIGINAL REQUEST:
E-commerce billing and invoicing DataGenerator component for Australia and New Zealand marketplaces. Generate 500 invoice records. Output:
<Metadata>
  <Record name="InvoiceRecord">
    <Field name="store_account" type="string"/>
    <Field name="bill_issued_on" type="date" nullable="false"/>
    <Field name="gross_total" type="decimal" length="9" scale="2"/>
    <Field name="gst_percent" type="number" nullable="true"/>
    <Field name="payment_window_days" type="long"/>
    <Field name="invoice_stage" type="string" nullable="false"/>
  </Record>
</Metadata>

Task: Generate 500 records. Use 10 merchant billing accounts: AU_STORE_001 to AU_STORE_005 and NZ_STORE_001 to NZ_STORE_005. Create 60 invoices for each Australian store and 40 invoices for each New Zealand store. Issue dates should span 2025-04-01 to 2025-06-30. Gross totals vary from 24.90 to 4200.00. `gst_percent` should usually be 10 for Australian accounts and 15 for New Zealand accounts, but leave it null for about 8% of records. `payment_window_days` should be 7, 14, or 30. `invoice_stage` must follow grouped rules: set it to DRAFT when `gst_percent` is null OR `bill_issued_on` falls on 2025-06-29 or 2025-06-30; otherwise set it to REVIEW when `store_account` starts with "NZ_" AND `gross_total` exceeds 2500.00 AND `payment_window_days` is 7; use a realistic mix of ISSUED and PAID for all remaining records, with PAID more common on older invoices.

PROPOSED CTL2 IMPLEMENTATION:
```ctl
//#CTL2:COMPILE

const string[] STORE_ACCOUNTS = [
    "AU_STORE_001", "AU_STORE_002", "AU_STORE_003", "AU_STORE_004", "AU_STORE_005",
    "NZ_STORE_001", "NZ_STORE_002", "NZ_STORE_003", "NZ_STORE_004", "NZ_STORE_005"
];

const integer INVOICES_PER_AU_STORE = 60;
const integer INVOICES_PER_NZ_STORE = 40;

const date MIN_DATE = 2025-04-01;
const date MAX_DATE = 2025-06-30;

const date DRAFT_CUTOFF_1 = 2025-06-29;
const date DRAFT_CUTOFF_2 = 2025-06-30;

const integer[] PAYMENT_WINDOWS = [7, 14, 30];

integer recordCounter = 0;

function boolean init() {
    setRandomSeed(42);
    return true;
}

function integer generate() {
    if (recordCounter >= 500) {
        return STOP;
    }

    integer storeIndex = recordCounter / 100;
    string storeAccount = STORE_ACCOUNTS[storeIndex];
    integer invoiceNumber = (recordCounter % 100) + 1;

    if (startsWith(storeAccount, "AU_") && invoiceNumber > INVOICES_PER_AU_STORE) {
        recordCounter++;
        return SKIP;
    }
    if (startsWith(storeAccount, "NZ_") && invoiceNumber > INVOICES_PER_NZ_STORE) {
        recordCounter++;
        return SKIP;
    }

    $out.0.store_account = storeAccount;

    // Determine issue date
    long minMillis = date2long(MIN_DATE);
    long maxMillis = date2long(MAX_DATE);
    long randomMillis = randomLong(minMillis, maxMillis);
    $out.0.bill_issued_on = long2date(randomMillis);

    // Gross total
    decimal grossMin = 24.90D;
    decimal grossMax = 4200.00D;
    $out.0.gross_total = randomDecimal(grossMin, grossMax);

    // GST percent
    number gstRate = null;
    if (randomInteger(1, 100) > 8) {  // 92% of records get a GST rate
        if (startsWith(storeAccount, "AU_")) {
            gstRate = 10.0;
        } else if (startsWith(storeAccount, "NZ_")) {
            gstRate = 15.0;
        }
    }
    $out.0.gst_percent = gstRate;

    // Payment window
    $out.0.payment_window_days = PAYMENT_WINDOWS[randomInteger(0, length(PAYMENT_WINDOWS) - 1)];

    // Invoice stage
    if (isnull($out.0.gst_percent) ||
        ($out.0.bill_issued_on >= DRAFT_CUTOFF_1 && $out.0.bill_issued_on <= DRAFT_CUTOFF_2)) {
        $out.0.invoice_stage = "DRAFT";
    } else if (startsWith(storeAccount, "NZ_") &&
               $out.0.gross_total > 2500.00D &&
               $out.0.payment_window_days == 7) {
        $out.0.invoice_stage = "REVIEW";
